-- ============================================================
-- Connect TVC -- realistic-scale sample data (DFW metro), v2.
-- Supersedes the previous version of this file (180 groups, 450 people,
-- flat city distribution — this migration was renumbered from 004 to 005
-- so it can run after 004_group_placement_details.sql, which it now
-- depends on). This version concentrates groups and
-- people into the DFW cities a church would realistically draw from, so
-- the Finder's exact-match rule (same city AND day-overlap AND same life
-- stage) actually surfaces multiple candidate groups per person instead
-- of 0-1 -- see the match-rate summary below, generated from this exact
-- dataset.
--
-- 320 groups, 600 people across 39 DFW cities (10 primary,
-- 8 secondary, 21 light long-tail). Every address embeds its city
-- correctly. Group day and person day-availability both draw from the same
-- weeknight-heavy distribution (Tue/Wed/Thu most common), and life stage
-- draws from the same realistic-roster skew for both -- deliberately
-- correlated, not independently random, since that's what actually
-- produces overlap.
--
-- Match-rate summary for this exact dataset (person has 0 / 1 / 2+
-- candidate groups under the app's default city+day+life-stage rule):
--   0 matches:  101 people (16.8%)
--   1 match:    124 people (20.7%)
--   2+ matches: 375 people (62.5%)
--   average matches per person: 2.80, max: 11
--
-- Deletes ALL existing rows in groups/people first (this app's own docs
-- flag all current sample/seed data as disposable placeholder data, not
-- real Connect TVC records), then inserts this dataset fresh. Safe to
-- re-run any time -- it always starts from a clean slate.
--
-- Run AFTER schema.sql + 003_person_geo_and_status.sql +
-- 004_group_placement_details.sql (needs the placement_details column).
-- ============================================================

delete from public.people;
delete from public.groups;

insert into public.groups
  (id, name, day, time, area, host, mentor, life, status, format, freq,
   capacity, members, childcare, topic, age_range, start_date, contact_email,
   address, description, placement_details)
